// The issue might be with specific merge patterns
// Try: defaults has __proto__ and baseObject also has properties
const payload = JSON.parse('{"__proto__":{"polluted":true},"key":"value"}');
console.log("\n3. payload from JSON.parse:");
console.log("   own keys:", Object.keys(payload));

defu({ existing: "keep" }, payload);
console.log("\n4. After defu({existing:'keep'}, payload):");
console.log("   polluted:", ({} as any).polluted);

// Another scenario: what about defu with two defaults?
defu({}, { __proto__: { polluted2: true } }, { other: "val" });
console.log("\n5. After defu({}, {__proto__: {polluted2: true}}, {other: 'val'}):");
console.log("   polluted2:", ({} as any).polluted2);
EOF
