const malicious = JSON.parse('{"__proto__":{"polluted":true},"key":"value"}');
console.log("=== Source object ===");
console.log("own property names:", Object.getOwnPropertyNames(malicious));
console.log("has own __proto__:", Object.prototype.hasOwnProperty.call(malicious, '__proto__'));
const descs = Object.getOwnPropertyDescriptors(malicious);
console.log("own property descriptors:", descs);

// Try with Object.create(null)
const target1 = Object.create(null);
Object.defineProperties(target1, descs);
console.log("\n=== After Object.defineProperties on null-proto ===");
console.log("own property names:", Object.getOwnPropertyNames(target1));
console.log("has own __proto__:", Object.prototype.hasOwnProperty.call(target1, '__proto__'));
console.log("target1.__proto__:", target1.__proto__);
console.log("target1.key:", target1.key);

// The key insight: when Object.defineProperties encounters __proto__ key,
// it might still use the setter!
// Let's verify by using a non-proto target
const target2: any = {};
Object.defineProperties(target2, descs);
console.log("\n=== After Object.defineProperties on regular object ===");
console.log("own property names:", Object.getOwnPropertyNames(target2));
console.log("has own __proto__:", Object.prototype.hasOwnProperty.call(target2, '__proto__'));
console.log("target2.__proto__ === Object.prototype:", target2.__proto__ === Object.prototype);
console.log("target2.key:", target2.key);

// Let's check what happens with a for-loop
const target3 = Object.create(null);
for (const key of Object.getOwnPropertyNames(malicious)) {
  const desc = Object.getOwnPropertyDescriptor(malicious, key)!;
  console.log(`Setting ${key}...`);
  try {
    Object.defineProperty(target3, key, desc);
    console.log(`  Success. value =`, target3[key]);
  } catch (e: any) {
    console.log(`  Error: ${e.message}`);
  }
}
console.log("\n=== After manual defineProperty loop on null-proto ===");
console.log("own property names:", Object.getOwnPropertyNames(target3));
console.log("target3.__proto__:", target3.__proto__);
console.log("target3.key:", target3.key);
console.log("Polluted?", (Object.prototype as any).polluted);
EOF
